def _today() -> str:
    return datetime.now(timezone.utc).date().isoformat()


def _ensure_db() -> None:
    db.init()


SIGNAL_ARCHETYPES = {
    "countable_catalyst",
    "cheap_optionality",
    "resolution_wording_trap",
    "stale_price",
    "actor_incentive_mismatch",
    "crowd_narrative_error",
    "repricing_watch",
}


def register(mcp):
    @mcp.tool()
    def record_signal_archetype(
        condition_id: str,
        primary_archetype: str,
        evidence: str,
        signal_quality_review_id: int | None = None,
        secondary_archetypes: list[str] | None = None,
        countable_catalyst_score: float = 0.0,
        cheap_optionality_score: float = 0.0,
        resolution_wording_trap_score: float = 0.0,
        stale_price_score: float = 0.0,
        actor_incentive_mismatch_score: float = 0.0,
        crowd_narrative_error_score: float = 0.0,
        repricing_watch_score: float = 0.0,
        anti_pattern_risk: str = "",
        repeatable_lesson: str = "",
    ) -> dict:
        """
        Classify a signal by the alpha pattern it represents.

        This protects the old model's useful instincts. Signal quality is not just
        "probability was right"; it is also the repeatable pattern: countable
        catalyst, cheap optionality, wording trap, stale price, actor incentives,
        crowd narrative error, or repricing watch.
        """
        _ensure_db()
        primary = primary_archetype.strip().lower()
        if primary not in SIGNAL_ARCHETYPES:
            return {"error": f"primary_archetype must be one of {sorted(SIGNAL_ARCHETYPES)}"}
        secondary_archetypes = [a.strip().lower() for a in (secondary_archetypes or []) if a.strip()]
        bad = [a for a in secondary_archetypes if a not in SIGNAL_ARCHETYPES]
        if bad:
            return {"error": f"unknown secondary archetypes: {bad}"}
        if not evidence.strip():
            return {"error": "evidence is required"}

        with db.connect() as conn:
            market = conn.execute(
                "SELECT question, vertical FROM markets WHERE condition_id = ?",
                (condition_id,),
            ).fetchone()
            if not market:
                return {"error": f"market {condition_id} not found"}
            if signal_quality_review_id is None:
                latest = conn.execute("""
                    SELECT id FROM signal_quality_reviews
                    WHERE condition_id = ?
                    ORDER BY created_at DESC LIMIT 1
                """, (condition_id,)).fetchone()
                signal_quality_review_id = latest["id"] if latest else None
            archetype_id = db.add_signal_archetype_review(
                conn,
                condition_id=condition_id,
                signal_quality_review_id=signal_quality_review_id,
                created_at=None,
                evaluator="claude-desktop",
                primary_archetype=primary,
                secondary_archetypes_json=json.dumps(secondary_archetypes),
                countable_catalyst_score=_clamp01(countable_catalyst_score),
                cheap_optionality_score=_clamp01(cheap_optionality_score),
                resolution_wording_trap_score=_clamp01(resolution_wording_trap_score),
                stale_price_score=_clamp01(stale_price_score),
                actor_incentive_mismatch_score=_clamp01(actor_incentive_mismatch_score),
                crowd_narrative_error_score=_clamp01(crowd_narrative_error_score),
                repricing_watch_score=_clamp01(repricing_watch_score),
                evidence=evidence.strip(),
                anti_pattern_risk=anti_pattern_risk or None,
                repeatable_lesson=repeatable_lesson or None,
            )
            conn.commit()

        return {
            "ok": True,
            "archetype_id": archetype_id,
            "condition_id": condition_id,
            "question": market["question"],
            "primary_archetype": primary,
            "secondary_archetypes": secondary_archetypes,
            "signal_quality_review_id": signal_quality_review_id,
        }



    @mcp.tool()
    def create_signal_benchmark_case(
        name: str,
        condition_id: str,
        expected_primary_archetype: str,
        expected_min_quality_score: float,
        expected_min_mtm_roi: float,
        expected_moved_toward: bool = True,
        expected_min_forecast_edge: float | None = None,
        reference_side: str = "",
        reference_entry_price: float | None = None,
        reference_probability_yes: float | None = None,
        reference_confidence: float | None = None,
        reference_spread: float | None = None,
        reference_snapshot_age_min: float | None = None,
        failure_if: str = "",
        notes: str = "",
        active: bool = True,
        case_kind: str = "positive",
        expected_gate_decision: str = "fire",
    ) -> dict:
        """
        Add an old signal as a regression benchmark case.

        Use this to prevent future versions from losing useful old instincts. A
        benchmark passes only if the latest quality/archetype reviews still meet the
        expected pattern and minimum quality thresholds.
        """
        _ensure_db()
        archetype = expected_primary_archetype.strip().lower()
        if archetype not in SIGNAL_ARCHETYPES:
            return {"error": f"expected_primary_archetype must be one of {sorted(SIGNAL_ARCHETYPES)}"}
        if not name.strip():
            return {"error": "name is required"}
        if expected_min_quality_score < 0 or expected_min_quality_score > 100:
            return {"error": "expected_min_quality_score must be 0-100"}

        side = reference_side.strip().upper() if reference_side else None
        if side and side not in {"YES", "NO"}:
            return {"error": "reference_side must be YES or NO"}
        if case_kind not in {"positive", "negative"}:
            return {"error": "case_kind must be positive or negative"}
        VALID_GATE_DECISIONS = {"fire", "block_edge", "block_spread",
                                "block_confidence", "block_spread_adj",
                                "block_snapshot_stale"}
        if expected_gate_decision not in VALID_GATE_DECISIONS:
            return {"error": f"expected_gate_decision must be one of {sorted(VALID_GATE_DECISIONS)}"}

        with db.connect() as conn:
            market = conn.execute(
                "SELECT question, vertical FROM markets WHERE condition_id = ?",
                (condition_id,),
            ).fetchone()
            if not market:
                return {"error": f"market {condition_id} not found"}
            case_id = db.add_signal_benchmark_case(
                conn,
                name=name.strip(),
                condition_id=condition_id,
                created_at=None,
                active=1 if active else 0,
                expected_primary_archetype=archetype,
                expected_min_quality_score=float(expected_min_quality_score),
                expected_min_mtm_roi=float(expected_min_mtm_roi),
                expected_moved_toward=1 if expected_moved_toward else 0,
                expected_min_forecast_edge=expected_min_forecast_edge,
                reference_side=side,
                reference_entry_price=reference_entry_price,
                reference_probability_yes=reference_probability_yes,
                reference_confidence=reference_confidence,
                reference_spread=reference_spread,
                reference_snapshot_age_min=reference_snapshot_age_min,
                failure_if=failure_if or None,
                notes=notes or None,
                case_kind=case_kind,
                expected_gate_decision=expected_gate_decision,
            )
            conn.commit()

        return {
            "ok": True,
            "case_id": case_id,
            "name": name.strip(),
            "condition_id": condition_id,
            "question": market["question"],
            "expected_primary_archetype": archetype,
            "expected_min_quality_score": expected_min_quality_score,
            "expected_min_mtm_roi_pct": round(expected_min_mtm_roi * 100, 1),
            "active": active,
        }



    @mcp.tool()
    def signal_regression_benchmark(active_only: bool = True) -> dict:
        """
        Run the regression suite for legacy signal instincts.

        This answers: did the current project still recognize the old hidden-gem
        archetypes and score them at least as strong as the benchmark expects?
        """
        _ensure_db()
        with db.connect() as conn:
            rows = conn.execute(f"""
                SELECT b.*, m.question, m.vertical
                FROM signal_benchmark_cases b
                JOIN markets m ON m.condition_id = b.condition_id
                {"WHERE b.active = 1" if active_only else ""}
                ORDER BY b.created_at ASC
            """).fetchall()

            cases = []
            for b in rows:
                quality = conn.execute("""
                    SELECT * FROM signal_quality_reviews
                    WHERE condition_id = ?
                    ORDER BY created_at DESC LIMIT 1
                """, (b["condition_id"],)).fetchone()
                archetype = conn.execute("""
                    SELECT * FROM signal_archetype_reviews
                    WHERE condition_id = ?
                    ORDER BY created_at DESC LIMIT 1
                """, (b["condition_id"],)).fetchone()

                case_kind = b["case_kind"] if "case_kind" in b.keys() else "positive"
                is_negative = case_kind == "negative"

                failures = []
                if quality is None:
                    failures.append("missing_signal_quality_review")
                # Negative cases don't require archetype review — they're examples
                # of bad signals, often pre-Stage-4 archetype classification.
                if archetype is None and not is_negative:
                    failures.append("missing_signal_archetype_review")

                if quality is not None:
                    if float(quality["total_score"]) < float(b["expected_min_quality_score"]):
                        failures.append("quality_score_below_expected")
                    if float(quality["mark_to_market_roi"] or 0.0) < float(b["expected_min_mtm_roi"]):
                        failures.append("mark_to_market_roi_below_expected")
                    if b["expected_moved_toward"] is not None:
                        expected_moved = bool(b["expected_moved_toward"])
                        if bool(quality["moved_toward_thesis"]) != expected_moved:
                            failures.append("moved_toward_thesis_mismatch")
                    if b["expected_min_forecast_edge"] is not None:
                        edge = quality["forecast_edge_at_entry"]
                        if edge is None or float(edge) < float(b["expected_min_forecast_edge"]):
                            failures.append("forecast_edge_below_expected")

                # Archetype mismatch only matters for positive cases
                if archetype is not None and not is_negative:
                    expected = b["expected_primary_archetype"]
                    secondary = json.loads(archetype["secondary_archetypes_json"] or "[]")
                    if archetype["primary_archetype"] != expected and expected not in secondary:
                        failures.append("archetype_mismatch")

                # Gate-decision check (Stage 0 gates against case's reference values).
                # Only meaningful if reference inputs are complete; old cases (Figure,
                # Gemini reasoning) predate the reference_confidence field.
                expected_gate = b["expected_gate_decision"] if "expected_gate_decision" in b.keys() else "fire"
                actual_gate = None
                gate_inputs_complete = (
                    b["reference_side"] and b["reference_entry_price"] is not None
                    and b["reference_probability_yes"] is not None
                    and b["reference_confidence"] is not None
                )
                if gate_inputs_complete:
                    case_kind = case_kind  # already defined above
                    # Prefer immutable benchmark inputs. Falling back to latest
                    # snapshot keeps old cases usable, but new cases should store
                    # reference_spread/reference_snapshot_age_min for stability.
                    spread = None
                    if "reference_spread" in b.keys() and b["reference_spread"] is not None:
                        spread = float(b["reference_spread"])
                    else:
                        snap = conn.execute("""
                            SELECT spread
                            FROM snapshots WHERE condition_id = ?
                            ORDER BY captured_at DESC LIMIT 1
                        """, (b["condition_id"],)).fetchone()
                        spread = float(snap["spread"]) if snap and snap["spread"] is not None else None

                    snapshot_age_min = (
                        float(b["reference_snapshot_age_min"])
                        if "reference_snapshot_age_min" in b.keys()
                        and b["reference_snapshot_age_min"] is not None
                        else None
                    )

                    # Compute reference edge from prob_yes vs entry
                    side = b["reference_side"]
                    p = float(b["reference_probability_yes"])
                    e = float(b["reference_entry_price"])
                    ref_edge = (p - e) if side == "YES" else ((1.0 - p) - e)
                    ref_conf = float(b["reference_confidence"])

                    if snapshot_age_min is not None and snapshot_age_min > config.MAX_SNAPSHOT_AGE_MIN:
                        actual_gate = "block_snapshot_stale"
                    else:
                        actual_gate = _no_signal_reason(ref_edge, ref_conf, spread)
                        if actual_gate is None:
                            actual_gate = "fire"
                        elif actual_gate == "edge_below_threshold":
                            actual_gate = "block_edge"
                        elif actual_gate == "spread_too_wide":
                            actual_gate = "block_spread"
                        elif actual_gate == "confidence_below_threshold":
                            actual_gate = "block_confidence"
                        elif actual_gate == "spread_adjusted_edge_below_threshold":
                            actual_gate = "block_spread_adj"
                    if actual_gate != expected_gate:
                        failures.append(f"gate_decision_mismatch_expected_{expected_gate}_got_{actual_gate}")
                cases.append({
                    "case_id": b["id"],
                    "name": b["name"],
                    "condition_id": b["condition_id"],
                    "question": b["question"],
                    "vertical": b["vertical"],
                    "case_kind": case_kind,
                    "passed": not failures,
                    "failures": failures,
                    "expected_primary_archetype": b["expected_primary_archetype"],
                    "actual_primary_archetype": archetype["primary_archetype"] if archetype else None,
                    "expected_gate_decision": expected_gate,
                    "actual_gate_decision": actual_gate,
                    "reference_spread": b["reference_spread"] if "reference_spread" in b.keys() else None,
                    "reference_snapshot_age_min": b["reference_snapshot_age_min"] if "reference_snapshot_age_min" in b.keys() else None,
                    "quality_score": quality["total_score"] if quality else None,
                    "min_quality_score": b["expected_min_quality_score"],
                    "mark_to_market_roi_pct": (
                        round(float(quality["mark_to_market_roi"] or 0.0) * 100, 1)
                        if quality else None
                    ),
                    "min_mark_to_market_roi_pct": round(float(b["expected_min_mtm_roi"]) * 100, 1),
                    "forecast_edge_at_entry": quality["forecast_edge_at_entry"] if quality else None,
                    "failure_if": b["failure_if"],
                    "notes": b["notes"],
                })

        passed = [c for c in cases if c["passed"]]
        return {
            "total_cases": len(cases),
            "passed": len(passed),
            "failed": len(cases) - len(passed),
            "pass_rate_pct": round(len(passed) / len(cases) * 100, 1) if cases else None,
            "status": "pass" if cases and len(passed) == len(cases) else "needs_attention",
            "cases": cases,
        }



    @mcp.tool()
    def record_signal_quality_review(
        condition_id: str,
        original_side: str,
        entry_price: float,
        stake_usd: float,
        probability_yes: float | None = None,
        confidence: float | None = None,
        market_price_at_pick: float | None = None,
        pick_created_at: str = "",
        signal_id: int | None = None,
        analysis_id: int | None = None,
        current_yes_price: float | None = None,
        current_side_price: float | None = None,
        current_snapshot_at: str = "",
        thesis_quality_score: float = 0.5,
        entry_quality_score: float = 0.5,
        catalyst_quality_score: float = 0.5,
        resolution_quality_score: float = 0.5,
        timing_quality_score: float = 0.5,
        risk_quality_score: float = 0.5,
        verdict: str = "",
        lessons: str = "",
        sources: list[str] | None = None,
    ) -> dict:
        """
        Backtest a signal as an early research find, even before final resolution.

        This is different from forecast_quality_report. It asks whether the pick
        found a market mispricing before the crowd repriced it: entry quality,
        mark-to-market ROI, movement toward the thesis, catalyst quality, timing,
        and resolution-risk awareness.
        """
        _ensure_db()
        sources = sources or []
        side = original_side.upper()
        if side not in {"YES", "NO"}:
            return {"error": "original_side must be YES or NO"}
        if entry_price <= 0 or entry_price >= 1:
            return {"error": "entry_price must be between 0 and 1"}
        if stake_usd <= 0:
            return {"error": "stake_usd must be positive"}

        with db.connect() as conn:
            market = conn.execute(
                "SELECT question, vertical, end_date FROM markets WHERE condition_id = ?",
                (condition_id,),
            ).fetchone()
            if not market:
                return {"error": f"market {condition_id} not found; call fetch_candidates or upsert the market first"}

            if signal_id is not None:
                sig = conn.execute("SELECT * FROM signals WHERE id = ?", (signal_id,)).fetchone()
                if not sig:
                    return {"error": f"signal {signal_id} not found"}
                pick_created_at = pick_created_at or sig["created_at"]
                probability_yes = probability_yes if probability_yes is not None else float(sig["claude_prob"])
                confidence = confidence if confidence is not None else float(sig["confidence"])

            if analysis_id is not None:
                analysis = conn.execute("SELECT * FROM analyses WHERE id = ?", (analysis_id,)).fetchone()
                if not analysis:
                    return {"error": f"analysis {analysis_id} not found"}
                pick_created_at = pick_created_at or analysis["created_at"]
                probability_yes = probability_yes if probability_yes is not None else float(analysis["probability_yes"])
                confidence = confidence if confidence is not None else float(analysis["confidence"])
                market_price_at_pick = (
                    market_price_at_pick
                    if market_price_at_pick is not None
                    else float(analysis["yes_price_at_analysis"])
                )

            ctx = _latest_execution_context(conn, condition_id)
            if current_yes_price is None:
                current_yes_price = ctx["market_price"] if ctx else None
            if current_snapshot_at == "" and ctx:
                current_snapshot_at = ctx["captured_at"]

            if current_side_price is None and ctx and current_yes_price is not None:
                if side == "YES":
                    current_side_price = ctx["best_bid"] if ctx["best_bid"] is not None else current_yes_price
                else:
                    current_side_price = 1.0 - ctx["best_ask"] if ctx["best_ask"] is not None else ctx["no_price"]

            if current_yes_price is None or current_side_price is None:
                return {"error": "current price unavailable; provide current_yes_price/current_side_price or add a snapshot"}

            market_price_at_pick = (
                market_price_at_pick
                if market_price_at_pick is not None
                else (entry_price if side == "YES" else 1.0 - entry_price)
            )
            shares = stake_usd / entry_price
            mark_to_market_value = shares * current_side_price
            mark_to_market_pnl = mark_to_market_value - stake_usd
            mark_to_market_roi = mark_to_market_pnl / stake_usd

            entry_yes_equivalent = entry_price if side == "YES" else 1.0 - entry_price
            price_delta_yes = current_yes_price - entry_yes_equivalent
            moved_toward_thesis = price_delta_yes > 0 if side == "YES" else price_delta_yes < 0

            forecast_edge_at_entry = None
            if probability_yes is not None:
                p = _clamp01(probability_yes)
                forecast_edge_at_entry = p - entry_price if side == "YES" else (1.0 - p) - entry_price

            repricing_speed_hours = None
            start_dt = _parse_dt(pick_created_at)
            end_dt = _parse_dt(current_snapshot_at)
            if start_dt and end_dt:
                repricing_speed_hours = max(0.0, (end_dt - start_dt).total_seconds() / 3600.0)

            thesis_quality_score = _clamp01(thesis_quality_score)
            entry_quality_score = _clamp01(entry_quality_score)
            catalyst_quality_score = _clamp01(catalyst_quality_score)
            resolution_quality_score = _clamp01(resolution_quality_score)
            timing_quality_score = _clamp01(timing_quality_score)
            risk_quality_score = _clamp01(risk_quality_score)
            total_score = _signal_quality_score(
                thesis_quality_score=thesis_quality_score,
                entry_quality_score=entry_quality_score,
                catalyst_quality_score=catalyst_quality_score,
                resolution_quality_score=resolution_quality_score,
                timing_quality_score=timing_quality_score,
                risk_quality_score=risk_quality_score,
                moved_toward_thesis=moved_toward_thesis,
                mark_to_market_roi=mark_to_market_roi,
            )
            grade = _quality_grade(total_score)

            if not verdict:
                if total_score >= 75 and mark_to_market_roi > 0:
                    verdict = "strong_early_signal"
                elif total_score >= 60 and mark_to_market_roi > 0:
                    verdict = "good_early_signal"
                elif moved_toward_thesis:
                    verdict = "directionally_right_but_low_quality"
                else:
                    verdict = "weak_or_unconfirmed_signal"

            review_id = db.add_signal_quality_review(
                conn,
                condition_id=condition_id,
                signal_id=signal_id,
                analysis_id=analysis_id,
                created_at=None,
                pick_created_at=pick_created_at or None,
                evaluator="claude-desktop",
                original_side=side,
                entry_price=entry_price,
                stake_usd=stake_usd,
                shares=shares,
                probability_yes=probability_yes,
                confidence=confidence,
                market_price_at_pick=market_price_at_pick,
                current_yes_price=current_yes_price,
                current_side_price=current_side_price,
                current_snapshot_at=current_snapshot_at or None,
                mark_to_market_value=mark_to_market_value,
                mark_to_market_pnl=mark_to_market_pnl,
                mark_to_market_roi=mark_to_market_roi,
                price_delta_yes=price_delta_yes,
                moved_toward_thesis=1 if moved_toward_thesis else 0,
                repricing_speed_hours=repricing_speed_hours,
                forecast_edge_at_entry=forecast_edge_at_entry,
                thesis_quality_score=thesis_quality_score,
                entry_quality_score=entry_quality_score,
                catalyst_quality_score=catalyst_quality_score,
                resolution_quality_score=resolution_quality_score,
                timing_quality_score=timing_quality_score,
                risk_quality_score=risk_quality_score,
                total_score=total_score,
                grade=grade,
                verdict=verdict,
                lessons=lessons or None,
                sources_json=json.dumps(sources),
            )
            conn.commit()

        return {
            "ok": True,
            "review_id": review_id,
            "condition_id": condition_id,
            "question": market["question"],
            "original_side": side,
            "entry_price": round(entry_price, 4),
            "stake_usd": round(stake_usd, 2),
            "shares": round(shares, 4),
            "current_yes_price": round(current_yes_price, 4),
            "current_side_price": round(current_side_price, 4),
            "mark_to_market_value": round(mark_to_market_value, 2),
            "mark_to_market_pnl": round(mark_to_market_pnl, 2),
            "mark_to_market_roi_pct": round(mark_to_market_roi * 100, 1),
            "price_delta_yes": round(price_delta_yes, 4),
            "moved_toward_thesis": moved_toward_thesis,
            "forecast_edge_at_entry": round(forecast_edge_at_entry, 4) if forecast_edge_at_entry is not None else None,
            "repricing_speed_hours": round(repricing_speed_hours, 2) if repricing_speed_hours is not None else None,
            "quality_score": total_score,
            "grade": grade,
            "verdict": verdict,
        }


